CREATE PROCEDURE dbo.AprobarOperacion
    @IdOperacion INT
AS
BEGIN
    UPDATE dbo.Operaciones
       SET Estado = 'APROBADA'
     WHERE IdOperacion = @IdOperacion
       AND Estado = 'PENDIENTE'
       AND Monto > 0;
END;

CREATE PROCEDURE dbo.RegistrarOperacion
    @IdOperacion INT,
    @TipoOperacion INT,
    @Monto DECIMAL(18,2)
AS
BEGIN
    IF @TipoOperacion = 2 AND @Monto > 0
    BEGIN
        INSERT INTO dbo.Operaciones(IdOperacion, TipoOperacion, Estado, Monto)
        VALUES (@IdOperacion, @TipoOperacion, 'PENDIENTE', @Monto);
    END
END;

