CREATE PROCEDURE dbo.RegistrarTraza
    @Mensaje NVARCHAR(200)
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO dbo.LogEjecucion(Mensaje, FechaRegistro)
    VALUES (@Mensaje, SYSUTCDATETIME());
END;
